<Section
  id="22-wmr"
  title=".22 Winchester Magnum Rimfire (.22 WMR)"
>
  <img
    src="/images/calibers/cartridges/22-wmr.png"
    alt=".22 Winchester Magnum Rimfire (.22 WMR)"
    style={{
      width: "41%",
      height: "auto",
      display: "block",
      margin: "0 auto 30px auto",
    }}
  />

  <p>
    Патронът <strong>.22 Winchester Magnum Rimfire (.22 WMR)</strong>, по-известен
    като <strong>.22 Magnum</strong>, е създаден през <strong>1959 г.</strong> от
    американската компания <strong>Winchester Repeating Arms Company</strong>.
    Целта му е да предложи значително по-мощен боеприпас с периферно
    възпламеняване, който да запази предимствата на малокалибрените патрони, но
    да осигурява по-висока начална скорост, по-голяма кинетична енергия и по-добра
    ефективност на по-големи дистанции.
  </p>
  <p>
  За разлика от <strong>.22 Long Rifle</strong>, патронът <strong>.22 WMR </strong>
  използва по-дълга и по-здрава гилза, която побира по-голям барутен заряд. Макар
  двата патрона да използват куршуми с приблизително еднакъв диаметър,
   <strong> те не са взаимозаменяеми</strong>. Оръжие, предназначено за
  <strong>.22 LR</strong>, не може безопасно да стреля с <strong>.22 WMR</strong>,
  тъй като размерите и работното налягане на двата патрона се различават
  съществено.
</p>

<p>
  Благодарение на високата си скорост и сравнително плоската траектория,
  <strong>.22 WMR</strong> намира широко приложение при лов на дребен дивеч и
  вредители. В много държави той се използва успешно за лов на зайци, лисици,
  чакали, мармоти и други животни с малки и средни размери. Патронът се предлага
  с разнообразни видове куршуми – оловни, полуоблечени, експанзивни и полимерни,
  което позволява избор според конкретното предназначение.
</p>

<p>
  Освен в ловни карабини, <strong>.22 WMR</strong> се използва и в револвери и
  компактни пистолети. При късоцевните оръжия обаче част от предимствата му се
  губят поради по-късата цев, която не позволява пълноценното изгаряне на
  барутния заряд. Въпреки това той остава най-мощният широко разпространен патрон
  с периферно възпламеняване и представлява естествената граница на
  възможностите на тази конструкция.
</p>
<h3>Интересен факт</h3>

<p>
  <strong>.22 WMR</strong> често е наричан
  <strong>"магнумът на патроните с периферно възпламеняване"</strong>.
  Въпреки малкия си калибър, началната му скорост може да достигне
  <strong>600–700 m/s</strong> при ловните карабини, което е почти двойно повече
  от тази на стандартния <strong>.22 LR</strong>.
</p>
</Section>
